-- vif-auteur-encore-present-refus-de-sortir — Il dit qu'il est chez lui et qu'il ne bougera pas
SELECT public.fn_cp_import_case('vif-auteur-encore-present-refus-de-sortir', '{"slug": "vif-auteur-encore-present-refus-de-sortir", "title": "Il dit qu''il est chez lui et qu''il ne bougera pas", "theme_slug": "violences-conjugales", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 21 heures. Vous êtes engagés au domicile de M. et Mme BARRAL suite à un appel d''un voisin ayant entendu des cris et un bruit de chute. À votre arrivée, Mme BARRAL présente une rougeur marquée au cou et pleure silencieusement, assise sur le canapé du salon. M. BARRAL, présent dans la même pièce, reste debout, bras croisés, et déclare d''emblée : « C''est chez moi ici, je suis chez moi, je ne vais nulle part. »\n\nIl n''est pas alcoolisé, reste apparemment calme mais fermement campé sur sa position, répétant que le logement est à son nom et qu''aucune loi ne peut l''obliger à quitter son propre domicile. Mme BARRAL, sans un mot, semble à la fois soulagée de votre présence et terrifiée à l''idée de rester seule avec lui après votre départ.\n\nAucune plainte n''a encore été formalisée à ce stade, l''échange venant tout juste de commencer.", "questions": [{"position": 1, "max_points": 5, "label": "Quelle est votre priorité immédiate avant d''aborder la question de l''éviction elle-même ?", "hint": "Discuter de qui doit partir avec les deux parties présentes dans la même pièce entretient la tension plutôt que de l''apaiser.", "perfect": "Ma priorité immédiate est de séparer physiquement M. et Mme BARRAL en les installant dans des pièces différentes ou en écartant l''un d''eux du salon, cette coprésence continue alimentant la tension et empêchant tout recueil serein de la parole de chacun.\n\nJe m''assure d''abord de l''état de santé de Mme BARRAL, la rougeur au cou et le bruit de chute rapporté par le voisin pouvant traduire des faits plus graves qu''une simple dispute verbale, ce qui nécessite une évaluation avant toute autre démarche.\n\nJe ne me lance pas dans une discussion sur la question de l''éviction de M. BARRAL tant que cette séparation n''est pas effective, cette question méritant d''être traitée à l''écart de la victime plutôt qu''en sa présence continue.\n\nJe reste attentive à la posture fermée de M. BARRAL, qui affiche un calme de façade mais une détermination affirmée à ne pas bouger, ce qui m''indique que la suite de l''échange demandera fermeté et méthode plutôt que simple discussion.", "points": [{"position": 1, "label": "Séparer physiquement les deux parties avant toute discussion", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : la coprésence continue alimente la tension et empêche le recueil serein.", "groups": [{"position": 1, "keywords": ["séparer physiquement", "avant toute discussion", "coprésence alimente la tension"]}]}, {"position": 2, "label": "S''assurer en priorité de l''état de santé de la victime", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "La rougeur et le bruit de chute peuvent traduire des faits plus graves.", "groups": [{"position": 1, "keywords": ["état de santé", "rougeur au cou", "bruit de chute"]}]}, {"position": 3, "label": "Ne pas aborder la question de l''éviction avant la séparation effective", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Traiter cette question à l''écart de la victime plutôt qu''en sa présence.", "groups": [{"position": 1, "keywords": ["ne pas aborder l''éviction avant", "à l''écart de la victime"]}]}, {"position": 4, "label": "Rester attentive à la posture fermée de l''auteur pour anticiper la suite", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Calme de façade mais détermination affirmée, demandant fermeté et méthode.", "groups": [{"position": 1, "keywords": ["posture fermée", "fermeté nécessaire", "anticiper la suite"]}]}]}, {"position": 2, "max_points": 5, "label": "M. BARRAL persiste à affirmer qu''être propriétaire du logement lui donne le droit absolu d''y rester. Comment répondez-vous à cet argument ?", "hint": "Le statut de propriétaire n''emporte pas automatiquement le droit de rester dans un contexte de violence caractérisée.", "perfect": "Je lui explique que la question de la propriété du logement ne détermine pas à elle seule le droit de s''y maintenir dans un contexte de violences caractérisées à l''encontre de sa conjointe, un dispositif légal spécifique existant précisément pour ce type de situation.\n\nJe ne me laisse pas convaincre par la répétition de son argument, aussi affirmé soit-il, en gardant à l''esprit que l''éviction du conjoint violent est une mesure prévue par la loi indépendamment du titre de propriété du logement.\n\nJe reste factuelle et professionnelle dans mon explication, sans entrer dans un débat juridique disproportionné avec lui, en me concentrant sur les éléments constatés qui justifient la mesure envisagée.\n\nJe m''assure que la décision d''éviction, si elle est prise, s''appuie sur des constatations précises et documentées, ce qui la rendra d''autant plus solide face à toute contestation ultérieure de sa part.", "points": [{"position": 1, "label": "Expliquer que la propriété ne détermine pas seule le droit de se maintenir", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : dispositif légal d''éviction existant indépendamment du titre de propriété.", "groups": [{"position": 1, "keywords": ["propriété ne détermine pas", "dispositif légal d''éviction", "indépendant du titre"]}]}, {"position": 2, "label": "Ne pas se laisser convaincre par la répétition de son argument", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "L''éviction reste prévue par la loi indépendamment de ce qu''il affirme.", "groups": [{"position": 1, "keywords": ["ne pas se laisser convaincre", "répétition de l''argument", "loi indépendante"]}]}, {"position": 3, "label": "Rester factuelle sans entrer dans un débat juridique disproportionné", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Se concentrer sur les éléments constatés plutôt qu''un débat prolongé.", "groups": [{"position": 1, "keywords": ["rester factuelle", "sans débat disproportionné", "éléments constatés"]}]}, {"position": 4, "label": "S''assurer que la décision s''appuie sur des constatations précises et documentées", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Solidifier la mesure face à une contestation ultérieure.", "groups": [{"position": 1, "keywords": ["constatations précises", "documentées", "solide face à contestation"]}]}]}, {"position": 3, "max_points": 5, "label": "Une fois l''éviction décidée, comment organisez-vous concrètement son départ et la suite immédiate pour Mme BARRAL ?", "hint": "L''éviction elle-même n''est qu''une étape ; l''après doit être anticipé avant de quitter les lieux.", "perfect": "Je procède à l''éviction de M. BARRAL de manière ferme et encadrée, en lui laissant un temps raisonnable pour rassembler des effets personnels strictement nécessaires sous surveillance plutôt que de le laisser circuler librement dans le logement.\n\nJe m''assure qu''il ne reprend pas contact immédiat avec Mme BARRAL une fois évincé, en le faisant quitter les lieux sans qu''un échange non maîtrisé ne se prolonge entre eux au moment du départ.\n\nJe reste ensuite auprès de Mme BARRAL pour recueillir sa parole dans un cadre enfin apaisé, en lui expliquant les suites possibles de cette intervention et les dispositifs de protection qui pourraient s''appliquer à sa situation.\n\nJe ne quitte pas les lieux sans m''assurer qu''elle dispose d''un moyen de contact en cas de nouvelle difficulté, notamment si M. BARRAL devait tenter de revenir malgré la mesure d''éviction prononcée.", "points": [{"position": 1, "label": "Procéder à l''éviction de manière ferme et encadrée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Temps raisonnable sous surveillance plutôt qu''une circulation libre.", "groups": [{"position": 1, "keywords": ["éviction ferme et encadrée", "sous surveillance", "temps raisonnable"]}]}, {"position": 2, "label": "S''assurer qu''il ne reprenne pas contact immédiat avec la victime", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Éviter un échange non maîtrisé au moment du départ.", "groups": [{"position": 1, "keywords": ["pas de contact immédiat", "départ sans échange", "non maîtrisé"]}]}, {"position": 3, "label": "Recueillir la parole de la victime dans un cadre enfin apaisé", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Expliquer les suites possibles et dispositifs de protection.", "groups": [{"position": 1, "keywords": ["recueillir la parole", "cadre apaisé", "dispositifs de protection"]}]}, {"position": 4, "label": "S''assurer qu''elle dispose d''un moyen de contact en cas de nouvelle difficulté", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Anticiper un éventuel retour de l''auteur malgré l''éviction.", "groups": [{"position": 1, "keywords": ["moyen de contact", "nouvelle difficulté", "retour malgré l''éviction"]}]}]}]}'::jsonb);

-- vif-violation-interdiction-de-contact — Il l'attend devant sa voiture alors qu'une mesure l'interdit
SELECT public.fn_cp_import_case('vif-violation-interdiction-de-contact', '{"slug": "vif-violation-interdiction-de-contact", "title": "Il l''attend devant sa voiture alors qu''une mesure l''interdit", "theme_slug": "violences-conjugales", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 16 heures. Vous êtes engagés sur le parking d''un supermarché où Mme DUCROS, effrayée, vous signale que son ex-compagnon, M. NOEL, se tient debout devant sa voiture, l''empêchant de partir. Elle précise qu''une mesure judiciaire lui interdit expressément tout contact avec elle depuis un mois, suite à des faits de violences déjà jugés.\n\nÀ votre arrivée, M. NOEL affirme calmement qu''il « faisait ses courses par hasard » et qu''il n''avait aucune intention de l''approcher, prétendant être aussi surpris qu''elle de cette rencontre fortuite sur ce parking qu''il fréquente, selon lui, habituellement.\n\nVous ne disposez pas immédiatement du document précisant les termes exacts de la mesure judiciaire évoquée, Mme DUCROS n''ayant pas cette copie sur elle mais affirmant avec certitude son existence et sa durée.", "questions": [{"position": 1, "max_points": 5, "label": "Comment procédez-vous pour vérifier la réalité et les termes exacts de cette mesure judiciaire avant d''agir ?", "hint": "Une affirmation, même sincère, doit être objectivée avant de fonder une décision sur son existence.", "perfect": "Je sollicite sans délai la vérification de l''existence et des termes précis de cette mesure judiciaire auprès des services compétents ou de mon central, plutôt que de me fier uniquement à l''affirmation orale de Mme DUCROS, aussi crédible soit-elle.\n\nJe maintiens dans l''intervalle une séparation physique claire entre les deux parties, en évitant tout nouvel échange direct entre eux le temps que cette vérification soit effectuée.\n\nJe recueille précisément les circonstances de cette rencontre selon Mme DUCROS, notamment depuis combien de temps M. NOEL se trouvait sur place avant son arrivée et la manière dont il s''est positionné devant son véhicule, ces éléments étant utiles pour apprécier l''intentionnalité de sa présence.\n\nJe ne relâche pas ma vigilance en attendant cette confirmation, en gardant à l''esprit que si la mesure existe réellement, chaque minute d''inaction pourrait constituer une tolérance implicite à sa violation.", "points": [{"position": 1, "label": "Vérifier l''existence et les termes exacts de la mesure auprès des services compétents", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : vérifier la mesure plutôt que se fier à la seule affirmation.", "groups": [{"position": 1, "keywords": ["vérifier la mesure", "services compétents", "pas seulement l''affirmation orale"]}]}, {"position": 2, "label": "Maintenir une séparation physique claire pendant la vérification", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Éviter tout nouvel échange direct le temps de la vérification.", "groups": [{"position": 1, "keywords": ["séparation physique", "pendant la vérification", "éviter l''échange direct"]}]}, {"position": 3, "label": "Recueillir précisément les circonstances de la rencontre", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Durée de présence et positionnement utiles pour apprécier l''intentionnalité.", "groups": [{"position": 1, "keywords": ["circonstances précises", "durée de présence", "intentionnalité"]}]}, {"position": 4, "label": "Ne pas relâcher la vigilance en attendant la confirmation", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Chaque minute d''inaction pourrait constituer une tolérance implicite.", "groups": [{"position": 1, "keywords": ["ne pas relâcher la vigilance", "tolérance implicite", "chaque minute compte"]}]}]}, {"position": 2, "max_points": 5, "label": "La mesure est confirmée existante et applicable. Comment traitez-vous l''explication de M. NOEL selon laquelle il se trouvait là « par hasard » ?", "hint": "L''intentionnalité de la présence est une question à examiner, pas à écarter d''emblée ni à accepter telle quelle.", "perfect": "Je ne rejette pas d''emblée son explication comme nécessairement mensongère, mais je ne l''accepte pas non plus telle quelle sans l''examiner au regard des éléments objectifs dont je dispose sur les circonstances de sa présence.\n\nJe considère que la violation de la mesure est caractérisée par le simple fait de sa présence à proximité immédiate de Mme DUCROS, indépendamment de la question de savoir si cette rencontre était intentionnelle ou fortuite, la mesure interdisant précisément ce type de contact.\n\nJe recueille sa version des faits de manière factuelle, sans lui donner le sentiment que son explication sera automatiquement retenue, tout en la consignant fidèlement pour la suite de la procédure.\n\nJe procède aux constatations et à la transmission de cette violation à l''autorité judiciaire compétente, qui appréciera in fine l''intentionnalité de cette rencontre au regard de l''ensemble des éléments du dossier.", "points": [{"position": 1, "label": "Ne pas rejeter ni accepter l''explication sans examen", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Examiner au regard des éléments objectifs disponibles.", "groups": [{"position": 1, "keywords": ["ne pas rejeter d''emblée", "ne pas accepter telle quelle", "examiner"]}]}, {"position": 2, "label": "Considérer la violation caractérisée par la simple présence, indépendamment de l''intentionnalité", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : vérifier la mesure et agir sans se laisser convaincre par l''explication.", "groups": [{"position": 1, "keywords": ["violation caractérisée", "simple présence", "indépendamment de l''intentionnalité"]}]}, {"position": 3, "label": "Recueillir sa version factuellement sans présumer qu''elle sera retenue", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Consigner fidèlement sans donner de garantie sur la suite.", "groups": [{"position": 1, "keywords": ["recueillir factuellement", "sans présumer", "consigner fidèlement"]}]}, {"position": 4, "label": "Transmettre la violation à l''autorité judiciaire pour appréciation finale", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "L''intentionnalité sera appréciée au regard de l''ensemble du dossier.", "groups": [{"position": 1, "keywords": ["transmettre à l''autorité judiciaire", "appréciation finale", "ensemble du dossier"]}]}]}, {"position": 3, "max_points": 5, "label": "Mme DUCROS, très éprouvée, vous demande si cette violation va « vraiment changer quelque chose » compte tenu de ses craintes que rien ne soit fait. Comment lui répondez-vous ?", "hint": "Sa lassitude et son scepticisme méritent une réponse honnête, ni fausse promesse ni découragement.", "perfect": "Je reconnais sa lassitude et la légitimité de son scepticisme, compte tenu de l''épreuve que représente le fait de devoir composer avec des tentatives de contact malgré une mesure censée la protéger.\n\nJe lui explique honnêtement que cette violation constatée et transmise constitue un élément concret qui vient s''ajouter au dossier judiciaire déjà existant, sans pour autant lui garantir une conséquence précise que je ne maîtrise pas.\n\nJe la rassure sur le sérieux avec lequel cette violation est traitée de mon côté, tout en restant honnête sur le fait que la décision finale appartient à l''autorité judiciaire et non à moi-même.\n\nJe reste disponible pour l''orienter vers des dispositifs d''accompagnement complémentaires, en particulier si elle se sent de plus en plus en insécurité malgré l''existence de cette mesure de protection.", "points": [{"position": 1, "label": "Reconnaître sa lassitude et la légitimité de son scepticisme", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Épreuve réelle de composer avec des tentatives malgré une mesure de protection.", "groups": [{"position": 1, "keywords": ["reconnaître la lassitude", "scepticisme légitime", "épreuve réelle"]}]}, {"position": 2, "label": "Expliquer honnêtement que cette violation s''ajoute concrètement au dossier", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Sans garantir une conséquence précise non maîtrisée.", "groups": [{"position": 1, "keywords": ["s''ajoute au dossier", "sans garantir", "élément concret"]}]}, {"position": 3, "label": "Rester honnête sur le fait que la décision appartient à l''autorité judiciaire", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Rassurer sur le sérieux du traitement sans excéder son propre rôle.", "groups": [{"position": 1, "keywords": ["décision judiciaire", "sérieux du traitement", "pas de ma compétence finale"]}]}, {"position": 4, "label": "Orienter vers des dispositifs d''accompagnement complémentaires", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Si elle se sent de plus en plus en insécurité.", "groups": [{"position": 1, "keywords": ["dispositifs d''accompagnement", "insécurité croissante", "orienter"]}]}]}]}'::jsonb);

-- vif-violences-psychologiques-sans-trace — Il ne m'a jamais touchée, c'est pire que ça
SELECT public.fn_cp_import_case('vif-violences-psychologiques-sans-trace', '{"slug": "vif-violences-psychologiques-sans-trace", "title": "Il ne m''a jamais touchée, c''est pire que ça", "theme_slug": "violences-conjugales", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 14 heures. Mme FABRE, 38 ans, se présente au commissariat pour dénoncer le comportement de son conjoint. Elle précise d''emblée : « Il ne m''a jamais touchée, c''est pire que ça. » Elle explique qu''il la rabaisse systématiquement devant leurs amis, contrôle ses fréquentations, lui répète qu''elle « ne vaut rien sans lui », et la surveille en consultant son téléphone chaque soir sans qu''elle ose s''y opposer.\n\nElle ne présente aucune trace physique, aucun événement daté avec précision au premier abord, son récit se présentant plutôt comme un ressenti global d''épuisement et de dévalorisation accumulée sur plusieurs années. Elle semble elle-même hésiter sur la manière de nommer ce qu''elle vit, oscillant entre minimisation et prise de conscience douloureuse.\n\nElle vous demande si ce qu''elle décrit « compte vraiment » pour la police, ou si elle doit attendre qu''il « passe à autre chose » pour que sa parole soit prise au sérieux.", "questions": [{"position": 1, "max_points": 5, "label": "Comment répondez-vous à sa question sur le fait de savoir si ce qu''elle décrit « compte vraiment » ?", "hint": "L''absence de trace physique ne signifie pas l''absence de violence caractérisée.", "perfect": "Je lui réponds sans hésitation que ce qu''elle décrit compte pleinement, la violence psychologique étant une forme de violence reconnue et caractérisée juridiquement, indépendamment de l''absence de toute trace physique.\n\nJe ne minimise à aucun moment son récit sous prétexte qu''il ne s''accompagne d''aucun coup ou blessure visible, en lui expliquant que le contrôle, le rabaissement systématique et la surveillance qu''elle décrit constituent des éléments constitutifs à part entière.\n\nJe reconnais la difficulté qu''elle éprouve elle-même à nommer ce qu''elle vit, ce qui est très fréquent pour ce type de violence qui s''installe progressivement et brouille les repères de la victime sur ce qui est acceptable ou non.\n\nJe l''encourage à ne pas attendre un événement plus grave ou plus visible pour venir en parler, sa démarche actuelle étant déjà pleinement légitime et recevable telle qu''elle se présente aujourd''hui.", "points": [{"position": 1, "label": "Répondre que ce qu''elle décrit compte pleinement", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : la violence psychologique est reconnue indépendamment de trace physique.", "groups": [{"position": 1, "keywords": ["compte pleinement", "violence psychologique reconnue", "indépendant de trace physique"]}]}, {"position": 2, "label": "Ne pas minimiser son récit en l''absence de coups ou blessures", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Contrôle, rabaissement et surveillance constituent des éléments à part entière.", "groups": [{"position": 1, "keywords": ["ne pas minimiser", "contrôle et rabaissement", "éléments constitutifs"]}]}, {"position": 3, "label": "Reconnaître sa difficulté à nommer ce qu''elle vit comme fréquente", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Installation progressive brouillant les repères de la victime.", "groups": [{"position": 1, "keywords": ["difficulté à nommer", "fréquente", "installation progressive"]}]}, {"position": 4, "label": "L''encourager à ne pas attendre un événement plus grave", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Sa démarche actuelle est déjà pleinement légitime.", "groups": [{"position": 1, "keywords": ["ne pas attendre", "démarche légitime aujourd''hui", "recevable"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment recueillez-vous concrètement son récit pour qu''il soit exploitable malgré l''absence d''éléments matériels ?", "hint": "Face à un ressenti global, la précision temporelle et factuelle devient l''outil principal de documentation.", "perfect": "Je l''aide à structurer son récit en identifiant des faits précis et datés autant que possible, plutôt que de me contenter d''un ressenti global d''épuisement qui serait plus difficile à documenter utilement.\n\nJe l''interroge sur des exemples concrets de rabaissement devant des tiers, sur les modalités précises du contrôle de ses fréquentations et de la surveillance de son téléphone, ce qui transforme un vécu diffus en éléments factuels exploitables.\n\nJe recherche si des tiers, comme les amis devant lesquels il la rabaisse, pourraient éventuellement témoigner de ces faits, ce qui viendrait objectiver son récit au-delà de sa seule parole.\n\nJe consigne fidèlement l''évolution et la répétition de ce comportement sur plusieurs années, cette durée et cette répétition étant elles-mêmes des éléments significatifs pour caractériser l''emprise qu''elle décrit.", "points": [{"position": 1, "label": "Structurer le récit en identifiant des faits précis et datés", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : recueillir des faits précis plutôt que des ressentis.", "groups": [{"position": 1, "keywords": ["faits précis et datés", "plutôt que ressenti global", "structurer le récit"]}]}, {"position": 2, "label": "Interroger sur des exemples concrets pour transformer le vécu en éléments factuels", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Modalités précises du contrôle et de la surveillance.", "groups": [{"position": 1, "keywords": ["exemples concrets", "modalités précises", "éléments factuels"]}]}, {"position": 3, "label": "Rechercher si des tiers pourraient témoigner", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Objectiver le récit au-delà de sa seule parole.", "groups": [{"position": 1, "keywords": ["témoins tiers", "objectiver", "au-delà de sa parole"]}]}, {"position": 4, "label": "Consigner la durée et la répétition sur plusieurs années", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Éléments significatifs pour caractériser l''emprise.", "groups": [{"position": 1, "keywords": ["durée et répétition", "plusieurs années", "caractériser l''emprise"]}]}]}, {"position": 3, "max_points": 5, "label": "Elle hésite à déposer plainte formellement aujourd''hui, craignant que ce ne soit « pas assez grave ». Comment l''accompagnez-vous dans cette décision ?", "hint": "Sa propre minimisation ne doit ni être combattue frontalement ni validée comme un renoncement définitif.", "perfect": "Je respecte son hésitation du jour sans la pousser à déposer plainte contre son gré, cette décision devant rester la sienne au moment où elle se sent prête à la prendre.\n\nJe lui propose, si elle le souhaite, de consigner d''ores et déjà les éléments de son récit sous une forme qui pourra être réactivée plus tard, ce qui lui évite de devoir tout reconstruire depuis le début si elle revient ultérieurement.\n\nJe ne valide pas son propre jugement selon lequel ce qu''elle vit ne serait « pas assez grave », en lui répétant avec constance que sa situation est prise au sérieux, sans pour autant la forcer à franchir une étape qu''elle ne se sent pas prête à franchir aujourd''hui.\n\nJe l''oriente vers des dispositifs d''accompagnement psychologique et associatif adaptés aux violences psychologiques, ce qui peut l''aider à cheminer vers sa propre décision à son rythme.", "points": [{"position": 1, "label": "Respecter son hésitation sans la pousser à déposer plainte contre son gré", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "La décision doit rester la sienne, à son propre rythme.", "groups": [{"position": 1, "keywords": ["respecter l''hésitation", "sans forcer", "sa décision"]}]}, {"position": 2, "label": "Proposer de consigner les éléments pour une réactivation ultérieure", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Éviter qu''elle doive tout reconstruire si elle revient plus tard.", "groups": [{"position": 1, "keywords": ["consigner pour plus tard", "réactivation ultérieure", "éviter de tout reconstruire"]}]}, {"position": 3, "label": "Ne pas valider son jugement que ce n''est « pas assez grave »", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Répéter que sa situation est prise au sérieux sans la forcer.", "groups": [{"position": 1, "keywords": ["ne pas valider la minimisation", "prise au sérieux", "sans forcer l''étape"]}]}, {"position": 4, "label": "Orienter vers des dispositifs d''accompagnement adaptés", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "L''aider à cheminer à son rythme vers sa propre décision.", "groups": [{"position": 1, "keywords": ["accompagnement psychologique", "associatif", "cheminer à son rythme"]}]}]}]}'::jsonb);

-- vif-emprise-victime-defend-son-conjoint — Elle vous reproche d'être venus et prend sa défense
SELECT public.fn_cp_import_case('vif-emprise-victime-defend-son-conjoint', '{"slug": "vif-emprise-victime-defend-son-conjoint", "title": "Elle vous reproche d''être venus et prend sa défense", "theme_slug": "violences-conjugales", "difficulty": "expert", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 35, "situation_text": "Il est 19 heures. Vous êtes engagés au domicile de Mme ISTRATE suite à un appel d''urgence qu''elle a elle-même passé plus tôt dans la soirée, visiblement paniquée, évoquant des coups reçus de la part de son conjoint. À votre arrivée, la situation semble s''être totalement inversée : Mme ISTRATE vous accueille avec hostilité, reprochant votre présence, affirmant qu''elle a « paniqué pour rien » et que son conjoint « n''a rien fait de mal ».\n\nElle présente pourtant une marque rouge visible à la mâchoire qu''elle attribue maintenant à une chute. Son conjoint, M. ISTRATE, reste en retrait mais silencieusement présent dans la pièce voisine, sa seule présence semblant peser sur chacune des paroles que prononce Mme ISTRATE devant vous.\n\nElle insiste pour que vous repartiez au plus vite, répétant qu''elle n''a besoin de rien et qu''elle regrette d''avoir appelé, sans jamais regarder directement M. ISTRATE mais en semblant constamment vérifier sa réaction du coin de l''œil.", "questions": [{"position": 1, "max_points": 5, "label": "Comment interprétez-vous ce retournement complet de la situation entre son appel initial et votre arrivée ?", "hint": "Ce phénomène est identifiable et documenté ; le reconnaître change la manière d''aborder la suite de l''intervention.", "perfect": "J''interprète ce retournement comme un phénomène caractéristique de l''emprise, où la présence de l''auteur suffit à faire taire ou à faire rétracter une victime qui, quelques instants plus tôt, avait pourtant elle-même sollicité une aide urgente.\n\nJe ne prends pas ce changement de discours comme une preuve que rien de grave ne s''est produit, la peur des représailles ou l''intériorisation de la loyauté envers l''auteur pouvant expliquer ce revirement bien plus qu''un simple excès initial de panique.\n\nJe reste attentive au langage non-verbal de Mme ISTRATE, notamment ses vérifications constantes de la réaction de son conjoint, qui traduisent une vigilance et une crainte incompatibles avec l''idée qu''elle serait réellement apaisée et sincère dans son discours actuel.\n\nJe ne me braque pas non plus contre elle en réaction à son hostilité apparente à mon égard, en comprenant que cette agressivité envers moi peut elle-même être une manière de protéger son conjoint sous la pression de sa présence.", "points": [{"position": 1, "label": "Interpréter ce retournement comme un phénomène caractéristique de l''emprise", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : la présence de l''auteur suffit à faire taire ou rétracter la victime.", "groups": [{"position": 1, "keywords": ["phénomène d''emprise", "présence de l''auteur", "faire rétracter"]}]}, {"position": 2, "label": "Ne pas prendre le changement de discours comme preuve qu''il ne s''est rien passé", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Peur des représailles ou loyauté envers l''auteur expliquant le revirement.", "groups": [{"position": 1, "keywords": ["pas une preuve", "peur des représailles", "loyauté envers l''auteur"]}]}, {"position": 3, "label": "Rester attentive au langage non-verbal incompatible avec un apaisement sincère", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Vérifications constantes traduisant vigilance et crainte.", "groups": [{"position": 1, "keywords": ["langage non-verbal", "vigilance et crainte", "pas apaisée sincèrement"]}]}, {"position": 4, "label": "Ne pas se braquer contre elle en réaction à son hostilité", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "L''hostilité peut être une façon de protéger le conjoint sous pression.", "groups": [{"position": 1, "keywords": ["ne pas se braquer", "protéger le conjoint", "sous pression"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment tentez-vous de créer une occasion de parler à Mme ISTRATE sans la présence directe de son conjoint ?", "hint": "L''objectif n''est pas de forcer une révélation mais de créer un espace où elle pourrait, si elle le souhaite, s''exprimer différemment.", "perfect": "Je cherche un prétexte naturel pour l''isoler brièvement de son conjoint, comme demander à la voir séparément selon une procédure habituelle, plutôt que de désigner explicitement mon intention de la faire parler loin de lui.\n\nJe m''assure que mon collègue reste avec M. ISTRATE pendant cet échange, ce qui crée un cadre plus confidentiel où elle pourrait, si elle le souhaite, exprimer une réalité différente de celle affichée en sa présence.\n\nJe ne la brusque pas et ne lui reproche pas son changement de discours, en évitant tout ton accusateur qui la braquerait davantage et renforcerait sa position de défense de son conjoint.\n\nJe reste attentive au fait que même dans ce cadre plus confidentiel, elle pourrait ne rien dire de plus par crainte de conséquences après notre départ, ce qui ne remet pas en cause la réalité de ce que j''ai pu moi-même constater à mon arrivée.", "points": [{"position": 1, "label": "Chercher un prétexte naturel pour l''isoler brièvement", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : maintenir la porte ouverte sans désigner explicitement l''intention.", "groups": [{"position": 1, "keywords": ["prétexte naturel", "isoler brièvement", "sans désigner l''intention"]}]}, {"position": 2, "label": "S''assurer d''un cadre confidentiel avec un collègue occupant le conjoint", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Permettre une expression différente en son absence.", "groups": [{"position": 1, "keywords": ["cadre confidentiel", "collègue avec le conjoint", "expression différente"]}]}, {"position": 3, "label": "Ne pas la brusquer ni lui reprocher son changement de discours", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Éviter un ton accusateur qui la braquerait davantage.", "groups": [{"position": 1, "keywords": ["ne pas brusquer", "pas de ton accusateur", "éviter de braquer"]}]}, {"position": 4, "label": "Accepter qu''elle puisse ne rien dire de plus même isolée", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Ne remet pas en cause la réalité constatée à l''arrivée.", "groups": [{"position": 1, "keywords": ["accepter le silence", "ne remet pas en cause", "constaté à l''arrivée"]}]}]}, {"position": 3, "max_points": 5, "label": "Elle ne révèle rien de plus et insiste pour que vous partiez. Comment clôturez-vous cette intervention en gardant la porte ouverte pour l''avenir ?", "hint": "Le poids fort de ce cas est précisément de ne pas se braquer et de préserver une possibilité de retour, même sans résultat immédiat.", "perfect": "Je ne pars pas sans avoir consigné avec précision l''ensemble de mes constatations, y compris son appel initial, la marque visible, et son changement de discours en présence de son conjoint, ces éléments ayant une valeur en soi indépendamment de sa position actuelle.\n\nJe lui laisse discrètement, si possible sans que son conjoint le remarque, des informations pratiques sur les dispositifs d''aide qu''elle pourra utiliser à sa propre initiative si sa situation évoluait.\n\nJe ne me braque pas contre elle en partant, en maintenant un ton respectueux malgré son hostilité apparente, ce qui préserve la possibilité qu''elle se souvienne de cette intervention comme un point d''appui plutôt que comme un jugement porté contre elle.\n\nJe garde à l''esprit que cette intervention, même sans révélation immédiate, s''inscrit dans une chronologie qui pourrait s''avérer précieuse si d''autres appels concernant ce couple devaient survenir à l''avenir.", "points": [{"position": 1, "label": "Consigner avec précision l''ensemble des constatations malgré l''absence de révélation", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Appel initial, marque visible, changement de discours ayant une valeur en soi.", "groups": [{"position": 1, "keywords": ["consigner précisément", "appel initial", "valeur en soi"]}]}, {"position": 2, "label": "Laisser discrètement des informations sur les dispositifs d''aide", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Utilisables à son initiative si la situation évolue.", "groups": [{"position": 1, "keywords": ["informations discrètes", "dispositifs d''aide", "à son initiative"]}]}, {"position": 3, "label": "Ne pas se braquer en partant, maintenir un ton respectueux", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : préserver la possibilité d''un point d''appui plutôt qu''un jugement.", "groups": [{"position": 1, "keywords": ["ne pas se braquer", "ton respectueux", "point d''appui"]}]}, {"position": 4, "label": "Considérer cette intervention comme utile pour une chronologie future", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Précieuse si d''autres appels concernant ce couple survenaient.", "groups": [{"position": 1, "keywords": ["chronologie future", "précieuse", "autres appels possibles"]}]}]}]}'::jsonb);

-- vif-enfants-temoins-directs — L'aînée raconte spontanément ce qu'elle a vu
SELECT public.fn_cp_import_case('vif-enfants-temoins-directs', '{"slug": "vif-enfants-temoins-directs", "title": "L''aînée raconte spontanément ce qu''elle a vu", "theme_slug": "violences-conjugales", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 20 h 15. Vous êtes engagés au domicile de Mme PELLETIER suite à des faits de violences conjugales, son conjoint ayant déjà été évincé du domicile par les collègues arrivés en premier. Mme PELLETIER, encore choquée, peine à formuler un récit cohérent des faits survenus quelques minutes plus tôt.\n\nLeur fille aînée, 8 ans, présente dans le salon, se met spontanément à raconter ce qu''elle a vu, avec des détails précis sur la position des uns et des autres et sur les mots exact échangés, sans que vous ne lui ayez posé la moindre question. Sa petite sœur de 4 ans reste silencieuse à ses côtés, serrant une peluche contre elle.\n\nMme PELLETIER, entendant sa fille parler ainsi devant vous, semble à la fois soulagée que la vérité soit dite et bouleversée que son enfant ait été témoin de cette scène et doive maintenant la raconter.", "questions": [{"position": 1, "max_points": 5, "label": "Comment accueillez-vous ce récit spontané de l''aînée sans compromettre sa fiabilité future ?", "hint": "Une parole d''enfant spontanée est précieuse mais fragile ; la manière de la recevoir compte autant que son contenu.", "perfect": "J''accueille ce récit spontané sans l''interrompre brutalement, tout en évitant de la relancer par des questions qui pourraient orienter ou enrichir artificiellement son témoignage au-delà de ce qu''elle exprime spontanément.\n\nJe ne lui pose aucune question suggestive ni ne lui demande de préciser à l''excès des détails qu''elle n''aborde pas d''elle-même, cette prudence étant essentielle pour préserver la valeur et la fiabilité de sa parole pour la suite de la procédure.\n\nJe reste dans une posture d''écoute attentive plutôt que d''interrogatoire, en la remerciant simplement pour ce qu''elle vient de partager sans la pousser à en dire davantage dans l''instant.\n\nJe consigne fidèlement ce qu''elle a spontanément rapporté, en notant précisément qu''aucune question n''a été posée pour l''obtenir, ce qui renforcera la valeur de ce témoignage lors d''une audition ultérieure menée par des professionnels formés à ce type de recueil.", "points": [{"position": 1, "label": "Accueillir le récit sans l''interrompre ni le relancer par des questions", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : recueillir sans interroger ni faire préciser à l''excès.", "groups": [{"position": 1, "keywords": ["accueillir sans relancer", "sans questions orientantes", "spontané"]}]}, {"position": 2, "label": "Ne poser aucune question suggestive ni pousser à préciser des détails", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Préserver la valeur et la fiabilité de la parole pour la suite.", "groups": [{"position": 1, "keywords": ["pas de question suggestive", "préserver la fiabilité", "sans pousser à préciser"]}]}, {"position": 3, "label": "Rester dans une posture d''écoute plutôt que d''interrogatoire", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Remercier simplement sans pousser à en dire davantage.", "groups": [{"position": 1, "keywords": ["écoute plutôt qu''interrogatoire", "remercier simplement", "pas de pression"]}]}, {"position": 4, "label": "Consigner en notant qu''aucune question n''a été posée pour l''obtenir", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Renforcer la valeur du témoignage pour une audition ultérieure formée.", "groups": [{"position": 1, "keywords": ["consigner sans question posée", "renforcer la valeur", "audition ultérieure"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gérez-vous en parallèle l''émotion de Mme PELLETIER face à ce récit de sa fille ?", "hint": "Le sentiment de culpabilité d''un parent face à l''exposition de son enfant à la violence mérite une attention spécifique.", "perfect": "Je reconnais l''ambivalence douloureuse que vit Mme PELLETIER, entre soulagement que la vérité soit dite et bouleversement de constater que sa fille a été témoin et doit maintenant porter ce récit, sans minimiser aucun des deux sentiments.\n\nJe ne la laisse pas s''enfoncer dans une culpabilité excessive à l''idée que l''exposition de sa fille aux violences serait de sa propre responsabilité, cette culpabilisation n''étant ni juste ni utile dans ce moment déjà si éprouvant pour elle.\n\nJe reste attentive à ne pas la faire répéter son propre récit immédiatement après celui de sa fille, ce qui pourrait créer une confusion ou une pression supplémentaire entre les deux témoignages recueillis coup sur coup.\n\nJe m''assure que les deux enfants, et pas seulement l''aînée qui s''est exprimée, bénéficient d''une attention et d''un réconfort adapté, la cadette silencieuse méritant également une vérification de son état malgré son absence de parole.", "points": [{"position": 1, "label": "Reconnaître l''ambivalence douloureuse de la mère sans minimiser", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Soulagement et bouleversement, deux sentiments légitimes à ne pas minimiser.", "groups": [{"position": 1, "keywords": ["ambivalence douloureuse", "sans minimiser", "deux sentiments légitimes"]}]}, {"position": 2, "label": "Ne pas la laisser s''enfoncer dans une culpabilité excessive", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "La culpabilisation n''est ni juste ni utile dans ce moment.", "groups": [{"position": 1, "keywords": ["ne pas culpabiliser", "pas juste ni utile", "moment éprouvant"]}]}, {"position": 3, "label": "Ne pas la faire répéter son récit immédiatement après celui de sa fille", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Éviter une confusion entre les deux témoignages recueillis coup sur coup.", "groups": [{"position": 1, "keywords": ["ne pas faire répéter", "éviter la confusion", "coup sur coup"]}]}, {"position": 4, "label": "S''assurer que la cadette silencieuse bénéficie aussi d''attention", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vérifier son état malgré son absence de parole.", "groups": [{"position": 1, "keywords": ["cadette silencieuse", "attention aussi", "vérifier son état"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment organisez-vous la suite de la prise en charge des deux enfants au-delà de cette soirée ?", "hint": "Le témoignage recueilli ce soir n''est qu''une étape ; la suite doit être pensée avec les bons professionnels.", "perfect": "Je transmets avec précision le récit spontané de l''aînée aux services compétents en protection de l''enfance, en indiquant clairement les conditions exactes dans lesquelles cette parole a été recueillie, sans interprétation ni reformulation de ma part.\n\nJe recommande qu''une audition formelle de l''aînée soit menée ultérieurement par des professionnels spécifiquement formés au recueil de la parole des mineurs, plutôt que de considérer que mon propre recueil informel de ce soir suffit à clore cette question.\n\nJe m''assure que les deux enfants bénéficient d''un suivi psychologique adapté à ce qu''ils viennent de vivre, cette exposition à la violence conjugale constituant en elle-même un traumatisme nécessitant un accompagnement au-delà de la seule résolution de l''incident du soir.\n\nJe reste attentive à ce que Mme PELLETIER ne se sente pas seule dans cette suite à organiser, en lui donnant des informations claires sur les prochaines étapes et les personnes qu''elle pourra contacter.", "points": [{"position": 1, "label": "Transmettre le récit avec précision aux services de protection de l''enfance", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Conditions exactes du recueil, sans interprétation ni reformulation.", "groups": [{"position": 1, "keywords": ["transmettre précisément", "protection de l''enfance", "sans interprétation"]}]}, {"position": 2, "label": "Recommander une audition formelle par des professionnels formés", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Le recueil informel du soir ne suffit pas à clore la question.", "groups": [{"position": 1, "keywords": ["audition formelle", "professionnels formés", "ne suffit pas à clore"]}]}, {"position": 3, "label": "S''assurer d''un suivi psychologique adapté pour les deux enfants", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "L''exposition à la violence constitue un traumatisme en soi.", "groups": [{"position": 1, "keywords": ["suivi psychologique", "traumatisme en soi", "au-delà de l''incident"]}]}, {"position": 4, "label": "Donner des informations claires à la mère sur les prochaines étapes", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Ne pas la laisser seule dans l''organisation de la suite.", "groups": [{"position": 1, "keywords": ["informations claires", "prochaines étapes", "pas seule"]}]}]}]}'::jsonb);

-- vif-violences-economiques — Elle n'a pas accès à son propre salaire depuis quatre ans
SELECT public.fn_cp_import_case('vif-violences-economiques', '{"slug": "vif-violences-economiques", "title": "Elle n''a pas accès à son propre salaire depuis quatre ans", "theme_slug": "violences-conjugales", "difficulty": "moyen", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 11 heures. Mme SIMON, 45 ans, se présente au commissariat pour évoquer sa situation conjugale, hésitante sur ce qu''elle vient réellement signaler. Elle explique que son mari gère l''intégralité des comptes du foyer depuis quatre ans, que son propre salaire est directement viré sur un compte auquel elle n''a plus accès, et qu''elle doit justifier chaque dépense, même la plus modeste, avant d''obtenir de l''argent de sa part.\n\nElle précise qu''il ne l''a jamais frappée et qu''elle ne sait même pas si ce qu''elle décrit constitue quelque chose que la police peut entendre, tant cette situation lui paraît à la fois pesante au quotidien et difficile à nommer comme une forme de violence à proprement parler.\n\nElle ajoute, presque en s''excusant, qu''elle a un niveau d''études supérieur au sien et qu''elle ne comprend pas elle-même comment elle en est arrivée à cette dépendance financière totale après quatre ans de cette organisation progressivement installée.", "questions": [{"position": 1, "max_points": 5, "label": "Comment qualifiez-vous ce qu''elle décrit et comment le lui présentez-vous ?", "hint": "Cette forme de violence est souvent la moins identifiée comme telle, y compris par ceux qui la vivent.", "perfect": "Je qualifie clairement ce qu''elle décrit comme relevant des violences économiques au sein du couple, une forme de violence reconnue à part entière bien que moins identifiée socialement que les violences physiques ou verbales.\n\nJe lui explique posément ce mécanisme de contrôle qu''elle vit, à savoir la privation d''accès à ses propres revenus et l''obligation de justifier chaque dépense, en la nommant clairement pour ce qu''elle est plutôt que de la laisser dans le flou où elle se trouve actuellement.\n\nJe ne minimise pas cette situation au prétexte de l''absence de violence physique, en soulignant que le contrôle financier peut être un instrument d''emprise aussi puissant que d''autres formes plus visibles de violence.\n\nJe reconnais sa surprise légitime face à cette situation qui s''est installée progressivement malgré son niveau d''études, ce type de mécanisme pouvant toucher n''importe qui indépendamment du niveau social ou éducatif, l''installation se faisant précisément par petites étapes qui ne se voient pas venir.", "points": [{"position": 1, "label": "Qualifier clairement la situation comme violence économique", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : identifier le mécanisme de contrôle et le nommer clairement.", "groups": [{"position": 1, "keywords": ["violence économique", "qualifier clairement", "forme reconnue"]}]}, {"position": 2, "label": "Expliquer posément le mécanisme de contrôle financier vécu", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Nommer clairement plutôt que la laisser dans le flou.", "groups": [{"position": 1, "keywords": ["expliquer le mécanisme", "nommer clairement", "sortir du flou"]}]}, {"position": 3, "label": "Ne pas minimiser en l''absence de violence physique", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Le contrôle financier peut être un instrument d''emprise puissant.", "groups": [{"position": 1, "keywords": ["ne pas minimiser", "instrument d''emprise", "sans violence physique"]}]}, {"position": 4, "label": "Reconnaître que ce mécanisme peut toucher n''importe qui", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Indépendamment du niveau social ou éducatif, installation progressive.", "groups": [{"position": 1, "keywords": ["peut toucher n''importe qui", "indépendant du niveau", "installation progressive"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment recueillez-vous les éléments concrets de ce mécanisme pour le documenter utilement ?", "hint": "Une violence économique se documente par des faits matériels précis, souvent disponibles sous forme de documents.", "perfect": "Je l''interroge précisément sur les modalités concrètes de ce contrôle : comment son salaire est-il viré, a-t-elle accès à des relevés bancaires, comment se déroule concrètement la justification de chaque dépense qu''elle évoque.\n\nJe l''oriente vers la collecte de documents matériels qui pourraient objectiver cette situation, comme des relevés de compte, des échanges de messages relatifs à ces demandes de justification, ou tout document attestant de l''absence d''accès à ses propres revenus.\n\nJe recueille la chronologie de l''installation de ce mécanisme sur ces quatre années, ce qui permet de comprendre comment ce contrôle s''est progressivement mis en place plutôt que d''être apparu d''un coup.\n\nJe reste attentive à ne pas la presser de fournir immédiatement tous ces éléments si elle n''y a pas accès facilement compte tenu de sa situation actuelle, en lui laissant la possibilité de revenir compléter son dossier progressivement.", "points": [{"position": 1, "label": "Interroger précisément sur les modalités concrètes du contrôle", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Virement du salaire, accès aux relevés, justification des dépenses.", "groups": [{"position": 1, "keywords": ["modalités concrètes", "virement du salaire", "justification des dépenses"]}]}, {"position": 2, "label": "Orienter vers la collecte de documents matériels objectivant la situation", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Relevés bancaires, messages relatifs aux demandes de justification.", "groups": [{"position": 1, "keywords": ["documents matériels", "relevés bancaires", "objectiver"]}]}, {"position": 3, "label": "Recueillir la chronologie de l''installation du mécanisme", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Comprendre la mise en place progressive sur quatre ans.", "groups": [{"position": 1, "keywords": ["chronologie", "installation progressive", "quatre ans"]}]}, {"position": 4, "label": "Ne pas la presser de fournir tous les éléments immédiatement", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Possibilité de compléter le dossier progressivement.", "groups": [{"position": 1, "keywords": ["ne pas presser", "compléter progressivement", "possibilité de revenir"]}]}]}, {"position": 3, "max_points": 5, "label": "Elle vous demande comment elle pourrait concrètement retrouver une autonomie financière sans nécessairement déposer plainte aujourd''hui. Que lui répondez-vous ?", "hint": "Sa question porte sur des solutions pratiques immédiates, distinctes de la question judiciaire.", "perfect": "Je distingue clairement pour elle la question judiciaire, qui concerne le dépôt de plainte éventuel, de la question pratique de son autonomie financière immédiate, qui peut être engagée indépendamment de sa décision sur le plan pénal.\n\nJe l''oriente vers des dispositifs d''accompagnement social et associatif spécialisés dans l''aide aux victimes de violences économiques, qui pourront l''aider concrètement à entamer des démarches pour récupérer un accès à ses propres revenus.\n\nJe ne lui donne pas de conseil juridique ou financier détaillé qui dépasserait mes propres compétences, en la redirigeant vers des professionnels mieux à même de l''accompagner dans ces démarches pratiques spécifiques.\n\nJe reste disponible pour recueillir sa plainte le jour où elle se sentira prête à le faire, sans que cette autonomisation progressive de sa situation financière ne soit conditionnée à une décision judiciaire immédiate de sa part.", "points": [{"position": 1, "label": "Distinguer la question judiciaire de l''autonomie financière immédiate", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Ces deux démarches peuvent être engagées indépendamment l''une de l''autre.", "groups": [{"position": 1, "keywords": ["distinguer judiciaire et financier", "indépendant", "deux démarches"]}]}, {"position": 2, "label": "Orienter vers des dispositifs spécialisés en violences économiques", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Accompagnement concret pour récupérer un accès aux revenus.", "groups": [{"position": 1, "keywords": ["dispositifs spécialisés", "accompagnement concret", "récupérer l''accès"]}]}, {"position": 3, "label": "Ne pas donner de conseil juridique ou financier détaillé hors compétence", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Rediriger vers des professionnels mieux à même d''accompagner.", "groups": [{"position": 1, "keywords": ["pas de conseil détaillé", "hors compétence", "rediriger"]}]}, {"position": 4, "label": "Rester disponible pour une plainte future sans condition", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Autonomisation financière non conditionnée à une décision judiciaire immédiate.", "groups": [{"position": 1, "keywords": ["disponible pour plus tard", "sans condition", "pas de conditionnement"]}]}]}]}'::jsonb);

-- vif-harcelement-post-separation-messages — Quatre-vingt-douze messages en deux jours, aucun n'est une menace
SELECT public.fn_cp_import_case('vif-harcelement-post-separation-messages', '{"slug": "vif-harcelement-post-separation-messages", "title": "Quatre-vingt-douze messages en deux jours, aucun n''est une menace", "theme_slug": "violences-conjugales", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 17 heures. Mme ROCHE, 29 ans, séparée de son ex-compagnon depuis trois semaines, se présente au commissariat avec son téléphone, sur lequel elle vous montre quatre-vingt-douze messages reçus en deux jours de sa part. Chaque message pris isolément semble anodin : des questions sur des affaires personnelles restées chez lui, des messages nostalgiques sur leur relation passée, des demandes de nouvelles répétées.\n\nAucun message ne contient d''insulte ni de menace explicite, ce qui la met en difficulté pour expliquer pourquoi elle se sent à ce point harcelée et oppressée par cette avalanche de sollicitations. Elle craint qu''on lui réponde que ce n''est « rien de grave » puisqu''aucun message pris seul ne semble constituer une menace caractérisée.\n\nElle précise qu''elle lui a pourtant demandé à plusieurs reprises, dans les premiers messages échangés, de cesser de la contacter ainsi, sans que cela ne change quoi que ce soit à la fréquence des envois.", "questions": [{"position": 1, "max_points": 5, "label": "Comment analysez-vous ces quatre-vingt-douze messages, pris isolément versus pris dans leur ensemble ?", "hint": "L''analyse message par message et l''analyse du volume global peuvent conduire à des conclusions très différentes.", "perfect": "J''analyse ces messages non pas isolément, ce qui les ferait effectivement paraître anodins un par un, mais dans leur ensemble et leur volume, la répétition massive en un temps aussi court constituant en elle-même l''élément caractéristique de ce qu''elle vit.\n\nJe considère que le harcèlement se caractérise précisément par cette accumulation et cette persistance, indépendamment du contenu de chaque message pris individuellement, ce volume représentant une intrusion continue dans sa vie qu''aucun message seul ne pourrait révéler.\n\nJe prends en compte le fait qu''elle lui a explicitement demandé d''arrêter dans les premiers échanges, ce refus de cesser malgré une demande claire constituant un élément central et non un simple détail de ce dossier.\n\nJe ne me laisse pas guider par l''apparence anodine de chaque message pour minimiser la gravité de l''ensemble, en gardant à l''esprit que cette fragmentation est précisément ce qui rend ce type de harcèlement difficile à faire reconnaître.", "points": [{"position": 1, "label": "Analyser le volume global plutôt que chaque message isolément", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : documenter la répétition plutôt que chercher un message décisif.", "groups": [{"position": 1, "keywords": ["volume global", "pas isolément", "répétition massive"]}]}, {"position": 2, "label": "Considérer le harcèlement comme caractérisé par l''accumulation et la persistance", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Indépendamment du contenu de chaque message pris individuellement.", "groups": [{"position": 1, "keywords": ["accumulation et persistance", "indépendant du contenu", "intrusion continue"]}]}, {"position": 3, "label": "Prendre en compte le refus de cesser malgré une demande explicite", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Élément central du dossier, pas un simple détail.", "groups": [{"position": 1, "keywords": ["refus de cesser", "demande explicite", "élément central"]}]}, {"position": 4, "label": "Ne pas se laisser guider par l''apparence anodine de chaque message", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "La fragmentation rend ce harcèlement difficile à faire reconnaître.", "groups": [{"position": 1, "keywords": ["apparence anodine", "fragmentation", "difficile à reconnaître"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment documentez-vous concrètement ce dossier pour qu''il soit exploitable malgré l''absence de messages individuellement menaçants ?", "hint": "Le volume et la chronologie deviennent les preuves principales à établir méthodiquement.", "perfect": "Je fais réaliser une capture méthodique de l''ensemble des quatre-vingt-douze messages avec leurs horodatages précis, ce qui permet d''établir objectivement la fréquence et l''intensité de cette sollicitation sur la période concernée.\n\nJe consigne précisément le moment où elle lui a demandé d''arrêter et l''absence de changement de comportement après cette demande, ce refus de cesser étant un élément clé indépendamment de la teneur de chaque message individuel.\n\nJe recueille son propre ressenti sur l''impact de cette avalanche de messages dans son quotidien, comme d''éventuelles difficultés de sommeil ou de concentration, ce qui objective concrètement le préjudice qu''elle subit.\n\nJe ne me contente pas d''examiner quelques messages représentatifs, en veillant à ce que l''intégralité du volume soit prise en compte dans le dossier constitué, cette exhaustivité étant précisément ce qui démontre la réalité du harcèlement.", "points": [{"position": 1, "label": "Réaliser une capture méthodique avec horodatages précis", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Établir objectivement la fréquence et l''intensité sur la période.", "groups": [{"position": 1, "keywords": ["capture méthodique", "horodatages précis", "fréquence objective"]}]}, {"position": 2, "label": "Consigner le moment de la demande d''arrêt et l''absence de changement", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Élément clé indépendamment de la teneur de chaque message.", "groups": [{"position": 1, "keywords": ["demande d''arrêt consignée", "absence de changement", "élément clé"]}]}, {"position": 3, "label": "Recueillir son ressenti sur l''impact concret dans son quotidien", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Objectiver le préjudice subi (sommeil, concentration).", "groups": [{"position": 1, "keywords": ["ressenti sur l''impact", "préjudice objectivé", "quotidien affecté"]}]}, {"position": 4, "label": "Ne pas se contenter de quelques messages représentatifs", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "L''exhaustivité démontre la réalité du harcèlement.", "groups": [{"position": 1, "keywords": ["pas seulement représentatifs", "exhaustivité", "démontrer la réalité"]}]}]}, {"position": 3, "max_points": 5, "label": "Elle craint que son dossier soit classé faute d''un message clairement menaçant. Comment la rassurez-vous honnêtement sur ce point ?", "hint": "Une réassurance honnête reconnaît les limites réelles tout en valorisant la solidité du dossier tel qu''il est constitué.", "perfect": "Je lui explique honnêtement que le harcèlement par messages répétés est une infraction reconnue en tant que telle, indépendamment de l''existence d''un message individuellement menaçant, ce qui répond directement à sa crainte principale.\n\nJe ne lui garantis pas une issue judiciaire précise que je ne maîtrise pas, mais je la rassure sur le fait que le dossier tel que documenté, avec le volume, la chronologie et le refus de cesser malgré sa demande, constitue un ensemble solide et exploitable.\n\nJe reste honnête sur le fait que l''appréciation finale appartient à l''autorité judiciaire, sans pour autant lui laisser penser que sa démarche serait vaine ou insuffisamment fondée pour être prise au sérieux.\n\nJe l''encourage à continuer de documenter tout nouveau message qu''elle recevrait, cette continuité renforçant encore le dossier si la situation venait à se poursuivre après le dépôt de sa plainte.", "points": [{"position": 1, "label": "Expliquer que le harcèlement par messages répétés est reconnu en tant que tel", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Répond directement à sa crainte de l''absence de message menaçant.", "groups": [{"position": 1, "keywords": ["harcèlement reconnu", "indépendant du message menaçant", "répond à la crainte"]}]}, {"position": 2, "label": "Rassurer sur la solidité du dossier sans garantir l''issue", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Volume, chronologie et refus de cesser constituent un ensemble solide.", "groups": [{"position": 1, "keywords": ["dossier solide", "sans garantir l''issue", "ensemble exploitable"]}]}, {"position": 3, "label": "Rester honnête sur l''appréciation finale sans décourager", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Ne pas laisser penser que la démarche serait vaine.", "groups": [{"position": 1, "keywords": ["appréciation finale", "sans décourager", "démarche pas vaine"]}]}, {"position": 4, "label": "L''encourager à continuer de documenter tout nouveau message", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Renforcer le dossier si la situation se poursuit après la plainte.", "groups": [{"position": 1, "keywords": ["continuer à documenter", "renforcer le dossier", "après la plainte"]}]}]}]}'::jsonb);

COMMIT;
